cards.content:
### Contoh

Module CommonJS lama tetap bisa dipakai dari ESM:

```js
// diskon.cjs (kode lama dari tim lain)
module.exports = { potong: (n, persen) => n - (n * persen) / 100 };

// kasir/layanan.js (ESM)
import diskon from '../diskon.cjs';
diskon.potong(20000, 10); // 18000
```

Kode lama tidak perlu ditulis ulang semuanya sekaligus. Bagian baru memakai ESM, bagian lama dipindahkan bertahap.

cards.code:
// === diskon.cjs ===
module.exports = { potong: (n, persen) => n - (n * persen) / 100 };
// === kasir/data.js ===
export const MENU = { K01: { nama: 'Kopi Susu', harga: 18000 }, R01: { nama: 'Roti Bakar', harga: 15000 } };
// === kasir/layanan.js ===
import diskon from '../diskon.cjs';
import { MENU } from './data.js';
export default function hitung(pesanan, persen = 0) {
  const kotor = pesanan.reduce((a, [kode, n]) => a + MENU[kode].harga * n, 0);
  return diskon.potong(kotor, persen);
}
// === kasir/index.js ===
export { default as hitung } from './layanan.js';
export { MENU } from './data.js';
// === main.js ===
import { hitung, MENU } from './kasir/index.js';
const pesanan = [['K01', 2], ['R01', 1]];
console.log(pesanan.map(([k, n]) => `${MENU[k].nama} x${n}`).join(', '));
console.log('Total:', hitung(pesanan));
console.log('Member:', hitung(pesanan, 10));

